package vn.edu.eaut.lab7.controller; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.*; @WebFilter("/admin/*") public class LoginFilter implements Filter {public void doFilter(ServletRequest rq,ServletResponse rs,FilterChain chain)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)rq;HttpServletResponse s=(HttpServletResponse)rs;if(r.getSession().getAttribute("user")==null){s.sendRedirect(r.getContextPath()+"/login");return;}chain.doFilter(rq,rs);}}